-- Authoritative Phase 2.5 policy reset. Policies are permissive ORs, so remove every prior application policy first.
do $$ declare p record; begin for p in select schemaname, tablename, policyname from pg_policies where schemaname='public' and tablename in ('profiles','rooms','room_members','messages','dm_threads') loop execute format('drop policy if exists %I on %I.%I',p.policyname,p.schemaname,p.tablename); end loop; end $$;
create or replace function public.require_authenticated() returns void language plpgsql stable security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; end $$;
create or replace function public.is_room_owner(target_room uuid, target_user uuid default auth.uid()) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from room_members where room_id=target_room and user_id=target_user and role='owner') $$;
create policy profiles_read on profiles for select to authenticated using (true);
create policy profiles_update_self on profiles for update to authenticated using(id=auth.uid()) with check(id=auth.uid());
create policy rooms_read on rooms for select to authenticated using (kind in ('world','interest') or (kind='custom' and not is_private) or is_room_member(id));
create policy membership_read on room_members for select to authenticated using (is_room_member(room_id));
create policy membership_join_public on room_members for insert to authenticated with check (user_id=auth.uid() and role='member' and exists(select 1 from rooms where id=room_id and kind in ('interest','custom') and not is_private));
create policy membership_owner_insert on room_members for insert to authenticated with check (is_room_owner(room_id) and role in ('member','moderator'));
create policy membership_owner_update on room_members for update to authenticated using (is_room_owner(room_id)) with check (is_room_owner(room_id) and role in ('member','moderator'));
create policy membership_moderator_update_member on room_members for update to authenticated using (is_room_moderator(room_id) and role='member') with check (role='member');
create policy membership_leave_or_manage on room_members for delete to authenticated using ((user_id=auth.uid() and role='member') or (is_room_owner(room_id) and role <> 'owner') or (is_room_moderator(room_id) and role='member'));
create policy messages_read on messages for select to authenticated using ((room_id is not null and exists(select 1 from rooms where id=room_id and (kind='world' or is_room_member(id)))) or (thread_id is not null and can_access_thread(thread_id)));
create policy messages_insert on messages for insert to authenticated with check (sender_id=auth.uid() and ((room_id is not null and exists(select 1 from rooms where id=room_id and (kind='world' or is_room_member(id)))) or (thread_id is not null and can_access_thread(thread_id))));
create policy messages_update_author on messages for update to authenticated using(sender_id=auth.uid()) with check(sender_id=auth.uid());
create policy messages_delete_author on messages for delete to authenticated using(sender_id=auth.uid());
create policy dm_threads_participant_read on dm_threads for select to authenticated using(auth.uid() in (participant_low,participant_high));
create or replace function public.get_or_create_dm_thread(target_user uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare low_id uuid; high_id uuid; result uuid; begin perform require_authenticated(); if target_user=auth.uid() then raise exception 'Cannot message yourself'; end if; low_id:=least(auth.uid(),target_user); high_id:=greatest(auth.uid(),target_user); insert into dm_threads(participant_low,participant_high) values(low_id,high_id) on conflict(participant_low,participant_high) do update set participant_low=excluded.participant_low returning id into result; return result; end $$;
revoke all on function public.require_authenticated(),public.is_room_owner(uuid,uuid),public.get_or_create_dm_thread(uuid) from public; grant execute on function public.is_room_owner(uuid,uuid),public.get_or_create_dm_thread(uuid) to authenticated;
